import { useState } from 'react';

export function Pagination() {
  const total = {{total_pages}};
  const [page, setPage] = useState(1);
  return (
    <div className="flex items-center gap-1">
      <button onClick={() => setPage(Math.max(1, page - 1))} disabled={page === 1} className="rounded border px-3 py-1 disabled:opacity-50">Prev</button>
      {Array.from({ length: total }, (_, i) => i + 1).map((n) => (
        <button key={n} onClick={() => setPage(n)}
          className={`rounded px-3 py-1 ${page === n ? 'bg-blue-600 text-white' : 'border'}`}>
          {n}
        </button>
      ))}
      <button onClick={() => setPage(Math.min(total, page + 1))} disabled={page === total} className="rounded border px-3 py-1 disabled:opacity-50">Next</button>
    </div>
  );
}
